  router.get('/variants/events', (req, res) => {
    if (rejectNonLocalRequest(req, res)) return;
    res.set({
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    });
    res.flushHeaders?.();

    const writeSnapshot = (snapshot: unknown): void => {
      try {
        const activeSnapshot =
          snapshot && typeof snapshot === 'object'
            ? {
                ...(snapshot as Record<string, unknown>),
                starting: inlineStartTracker.isStarting(),
              }
            : snapshot;
        res.write(`data: ${JSON.stringify(stampLiveness(activeSnapshot))}\n\n`);
      } catch (err) {
        log.warn('SSE write failed (client likely disconnected)', err);
      }
    };

    writeSnapshot(orchestrator.buildActiveSnapshot());

    const unsubscribe = orchestrator.subscribeToEvents(writeSnapshot);
    const unsubscribeLiveness =
      bridge && typeof bridge.onWatcherLivenessChange === 'function'
        ? bridge.onWatcherLivenessChange(() => {
            writeSnapshot(orchestrator.buildActiveSnapshot());
          })
        : undefined;
    const releaseUiClient = orchestrator.registerUiClient();
    const heartbeat = setInterval(() => {
      try {
        touchActiveVariantSession();
        res.write(': heartbeat\n\n');
      } catch {}
    }, 30_000);

    req.on('close', () => {
      clearInterval(heartbeat);
      unsubscribe();
      unsubscribeLiveness?.();
      releaseUiClient();
      try {
        res.end();
      } catch {}
    });
  });

  router.get('/variants/history', async (req, res) => {
    if (rejectNonLocalRequest(req, res)) return;
    const projectPath = resolveProjectPath(req.query.projectPath);
    if (!projectPath) {
      res.status(400).json({
        errorCode: 'RUNTIME_VALIDATION_FAILED',
        message:
          'No projectPath available — pass ?projectPath=<abs> or open a project in the visual editor.',
      });
      return;
    }
    const statusParam =
      typeof req.query.status === 'string' ? req.query.status : undefined;
    if (
      statusParam &&
      !HISTORY_STATUSES.has(statusParam as VariantHistoryStatus)
    ) {
      res.status(400).json({
        errorCode: 'SCHEMA_VALIDATION_FAILED',
        message: `Invalid status '${statusParam}' — expected one of ${[...HISTORY_STATUSES].join(', ')}.`,
      });
      return;
    }
    const limitRaw = req.query.limit;
    const limit =
      typeof limitRaw === 'string' && limitRaw.length > 0
        ? Number.parseInt(limitRaw, 10)
        : undefined;
    if (limit !== undefined && (!Number.isFinite(limit) || limit <= 0)) {
      res.status(400).json({
        errorCode: 'SCHEMA_VALIDATION_FAILED',
        message: `Invalid limit '${limitRaw}' — expected a positive integer.`,
      });
      return;
    }
    try {
      const entries = (
        await Promise.all(
          resolveHistoryProjectPaths({ projectPath }).map(
            (historyProjectPath) =>
              variantHistory.listVariantsFromIndex({
                projectPath: historyProjectPath,
                status: statusParam as VariantHistoryStatus | undefined,
              }),
          ),
        )
      ).flat();
      const entriesById = new Map<string, (typeof entries)[number]>();
      for (const entry of entries) {
        entriesById.set(
          `${entry.manifest.sessionId}:${entry.manifest.variantId}`,
          entry,
        );
      }
      const uniqueEntries = Array.from(entriesById.values()).sort((a, b) =>
        b.manifest.createdAt.localeCompare(a.manifest.createdAt),
      );
      const limitedEntries =
        limit !== undefined ? uniqueEntries.slice(0, limit) : uniqueEntries;
      const visibleEntries =
        statusParam === 'removed'
          ? limitedEntries
          : limitedEntries.filter(
              (entry) =>
                entry.manifest.status !== 'removed' &&
                entry.manifest.status !== 'cancelled',
            );
      res.json({
        projectPath,
        variants: visibleEntries.map((entry): VariantHistoryRow => ({
          sessionId: entry.manifest.sessionId,
          variantId: entry.manifest.variantId,
          requestId: entry.manifest.requestId,
          directionRef: entry.manifest.directionRef,
          label: entry.manifest.label,
          brief: entry.manifest.brief,
          references: entry.manifest.references,
          previewRoutes: entry.manifest.previewRoutes,
          runLabel:
            entry.manifest.runLabel ??
            deriveRunLabel(entry.manifest.sessionPrompt),
          kind: manifestKind(entry.manifest),
          projectKind: entry.manifest.projectKind,
          status: entry.manifest.status,
          createdAt: entry.manifest.createdAt,
          statusChangedAt: entry.manifest.statusChangedAt,
          changedFilesCount: entry.manifest.changedFilesCount,
          hasStaticPreview: entry.hasStaticPreview,
          preview: entry.manifest.preview,
          artifact: entry.manifest.artifact,
          parentVariant: entry.manifest.parentVariant,
          ...(entry.manifest.serve ? { serve: entry.manifest.serve } : {}),
          hasTree: Boolean(entry.manifest.tree),
          ...(entry.manifest.runtime
            ? { runtime: entry.manifest.runtime }
            : {}),
        })),
      });
    } catch (err) {
      sendError(res, err);
    }
  });

  router.get(
    '/variants/:sessionId/:variantId/references/:referenceId/image',
    async (req, res) => {
      if (rejectNonLocalRequest(req, res)) return;
      const targetSchema = z.object({
        sessionId: z.string().regex(/^[A-Za-z0-9_-]+$/),
        variantId: z.string().regex(/^[A-Za-z0-9_-]+$/),
      });
      const parsed = targetSchema
        .extend({ referenceId: z.string().min(1).max(512) })
        .safeParse(req.params);
      if (!parsed.success) {
        res.status(400).json({ error: 'Invalid reference identity' });
        return;
      }
      const projectPath = resolveProjectPath(req.query.projectPath);
      if (!projectPath) {
        res.status(400).json({ error: 'Project path is required' });
        return;
      }
      const inputSchema = z.object({
        references: z.array(variantReferenceSchema).optional(),
        context: variantWorkItemContextSchema.optional(),
        adoptedFrom: targetSchema.optional(),
        sourceVariantId: z
          .string()
          .regex(/^[A-Za-z0-9_-]+$/)
          .optional(),
      });
      const visited = new Set<string>();
      const readImage = async (target: {
        sessionId: string;
        variantId: string;
      }): Promise<ReferenceImage | null> => {
        const key = `${target.sessionId}:${target.variantId}`;
        if (visited.has(key)) return null;
        visited.add(key);
        const found = await findHistoryVariant({ projectPath, ...target });
        if (found) {
          return variantHistory.getReferenceImage({
            projectPath: found.projectPath,
            ...target,
            referenceId: parsed.data.referenceId,
          });
        }
        let workItemInput: VariantWorkItemInput | undefined;
        try {
          workItemInput = orchestrator.getVariantWorkItemInput(
            target.sessionId,
            target.variantId,
          );
        } catch (error) {
          if (
            error instanceof AgentVariantsError &&
            ['SESSION_NOT_FOUND', 'WORK_ITEM_NOT_FOUND'].includes(error.code)
          )
            return null;
          throw error;
        }
        const input = inputSchema.safeParse(workItemInput);
        if (!input.success) return null;
        const reference = mergeVariantReferences(input.data.references)?.find(
          (item) => item.id === parsed.data.referenceId,
        );
        if (!reference?.image) return null;
        const current = await readContextReferenceImage({
          reference,
          context: input.data.context,
          roots: resolveHistoryProjectPaths({
            projectPath,
            sessionId: target.sessionId,
          }).map((candidate) =>
            path.join(
              variantHistory.store.storage.resolve(candidate).dataDirectory,
              'variant-context',
            ),
          ),
        });
        if (current) return current;
        const parent =
          input.data.adoptedFrom ??
          (input.data.sourceVariantId
            ? {
                sessionId: target.sessionId,
                variantId: input.data.sourceVariantId,
              }
            : undefined);
        if (!parent) return null;
        const inherited = await readImage(parent);
        return inherited &&
          inherited.mimeType === reference.image.mimeType &&
          createHash('sha256').update(inherited.body).digest('hex') ===
            reference.image.hash
          ? inherited
          : null;
      };
      try {
        const image = await readImage(parsed.data);
        if (!image) {
          res.status(404).json({ error: 'Reference image is unavailable' });
          return;
        }
        res
          .type(image.mimeType)
          .set('Cache-Control', 'private, no-store')
          .set('X-Content-Type-Options', 'nosniff')
          .send(image.body);
      } catch (error) {
        sendError(res, error);
      }
    },
  );

