  postOperation('/variants/:sessionId/canvas/deploy', async (req, res) => {
    if (rejectNonLocalRequest(req, res)) return;
    const sessionId = req.params.sessionId;

    const flags = await getFeatureFlags({
      userKey: getConfigFeatureFlagUserKey({ headers: req.headers }),
    });
    if (rejectDisabledShare({ flags, res, isCanvas: true })) return;

    const parsed = canvasDeployBody.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({
        errorCode: 'SCHEMA_VALIDATION_FAILED',
        message: parsed.error.message,
      });
      return;
    }
    const projectPath = resolveProjectPath(parsed.data.projectPath);
    if (!projectPath) {
      res.status(400).json({
        errorCode: 'RUNTIME_VALIDATION_FAILED',
        message:
          'No projectPath available — pass projectPath or open a project in the visual editor.',
      });
      return;
    }

    try {
      const variantIds = [...new Set(parsed.data.variantIds)];
      const canvasVariants: Array<{
        projectPath: string;
        detail: VariantHistoryDetail;
      }> = [];
      const deployedVariants: DeployedVariant[] = [];
      let sessionPrompt = '';
      let canvasHistoryProjectPath = projectPath;
      for (const variantId of variantIds) {
        const found = await findHistoryVariant({
          projectPath,
          sessionId,
          variantId,
        });
        if (!found) {
          res.status(404).json({
            errorCode: 'WORK_ITEM_NOT_FOUND',
            message: `Variant '${variantId}' not found in history.`,
          });
          return;
        }
        canvasHistoryProjectPath = found.projectPath;
        const variant = found.detail;
        if (variant.manifest.preview.kind !== 'static') {
          res.status(422).json({
            errorCode: 'RUNTIME_VALIDATION_FAILED',
            message:
              'Canvas sharing only supports static preview directions. Share buildable app directions individually.',
          });
          return;
        }
        if (!sessionPrompt) {
          sessionPrompt = variant.manifest.sessionPrompt;
        }
        canvasVariants.push(found);
      }

      for (const found of canvasVariants) {
        const variant = found.detail;
        const deployed = await deployPersistedVariant({
          projectPath: found.projectPath,
          sessionId,
          variant,
          reuseExisting: false,
        });
        if (!deployed.ok) {
          res.status(deployed.status).json({
            errorCode: deployed.errorCode,
            message: deployed.message,
          });
          return;
        }
        deployedVariants.push(deployed.variant);
      }

      const html = buildCanvasSharePage({
        sessionPrompt,
        variants: deployedVariants,
      });
      const canvas = await deployService.deployHtml(html, {
        title: getCanvasShareTitle(sessionPrompt),
      });
      const deployedAt = new Date().toISOString();
      const canvasDeployment = {
        deployId: canvas.deployId,
        shareUrl: canvas.shareUrl,
        deployedAt,
        variants: deployedVariants.map((variant) => ({
          variantId: variant.variantId,
          deployId: variant.deployId,
          shareUrl: variant.shareUrl,
        })),
      };
      let historyWarning: string | undefined;
      try {
        await variantHistory.recordCanvasDeployment({
          projectPath: canvasHistoryProjectPath,
          sessionId,
          deployment: canvasDeployment,
        });
      } catch (err) {
        historyWarning = 'Canvas history could not be recorded.';
        log.warn('Canvas deploy history record failed', err);
      }
      res.json({
        deployId: canvas.deployId,
        shareUrl: canvas.shareUrl,
        deployedAt,
        variants: deployedVariants,
        ...(historyWarning ? { historyWarning } : {}),
      });
    } catch (err) {
      log.error('Canvas deploy failed', err);
      const message = errorMessage(err, 'Deploy failed.');
      const detail =
        err && typeof err === 'object' && 'detail' in err
          ? String((err as { detail?: unknown }).detail ?? '')
          : '';
      res.status(500).json({
        errorCode: 'RUNTIME_VALIDATION_FAILED',
        message,
        ...(detail ? { detail } : {}),
      });
    }
  });

