const serveHistoryPreview = async (
  req: Request,
  res: Response,
  variantHistory: VariantHistoryService,
  resolveProjectPath: (raw: unknown) => string | null,
  resolveHistoryProjectPaths: (params: {
    projectPath: string;
    sessionId?: string;
  }) => string[],
  {
    isDocument,
    isSiteRelative,
  }: { isDocument: boolean; isSiteRelative?: boolean },
  previewBridge?: VariantPreviewBridgeOptions,
): Promise<void> => {
  if (rejectNonLocalRequest(req, res)) return;
  const invalidRawAssetPath = isSiteRelative
    ? null
    : getInvalidRawHistoryPreviewAssetPath(req.originalUrl);
  if (invalidRawAssetPath) {
    res.status(400).json({
      errorCode: 'SCHEMA_VALIDATION_FAILED',
      message: `Variant history preview: invalid assetPath '${invalidRawAssetPath}'`,
    });
    return;
  }
  const projectScope =
    req.params.projectPath === 'current' ? undefined : req.params.projectPath;
  const projectPath = resolveProjectPath(
    isSiteRelative ? projectScope : req.query.projectPath,
  );
  if (!projectPath) {
    res.status(400).json({
      errorCode: 'RUNTIME_VALIDATION_FAILED',
      message:
        'No projectPath available — pass ?projectPath=<abs> or open a project in the visual editor.',
    });
    return;
  }

  const rawAssetPath = req.params.assetPath;
  let assetPath: string | null = null;
  if (Array.isArray(rawAssetPath)) {
    assetPath = rawAssetPath.join('/');
  } else if (typeof rawAssetPath === 'string') {
    assetPath = rawAssetPath;
  }
  const sessionId = Array.isArray(req.params.sessionId)
    ? req.params.sessionId[0]
    : req.params.sessionId;
  const variantId = Array.isArray(req.params.variantId)
    ? req.params.variantId[0]
    : req.params.variantId;

  try {
    let file: Awaited<
      ReturnType<VariantHistoryService['readStaticPreviewFile']>
    > = null;
    for (const historyProjectPath of resolveHistoryProjectPaths({
      projectPath,
      sessionId,
    })) {
      file = await variantHistory.readStaticPreviewFile({
        projectPath: historyProjectPath,
        sessionId,
        variantId,
        assetPath,
        isSiteRelative,
      });
      if (file) {
        break;
      }
    }
    if (!file) {
      res.status(404).json({
        errorCode: 'WORK_ITEM_NOT_FOUND',
        message: 'No static preview file persisted for that variant.',
      });
      return;
    }
    if (isDocument) {
      const previewRoot = `/api/variants/history/${encodeURIComponent(sessionId)}/${encodeURIComponent(variantId)}/preview/`;
      const entryPath = file.relativePath
        .split('/')
        .map(encodeURIComponent)
        .join('/');
      const queryIndex = req.originalUrl.indexOf('?');
      const query = queryIndex === -1 ? '' : req.originalUrl.slice(queryIndex);
      res
        .set('Cache-Control', 'no-store')
        .redirect(302, previewRoot + entryPath + query);
      return;
    }
    const contentType =
      path.extname(file.absolutePath) || 'application/octet-stream';
    res.status(200).type(contentType).set('Cache-Control', 'no-store');
    if (file.isHtml) {
      sendStaticPreviewHtml({
        res,
        html: file.body.toString('utf8'),
        previewBridge,
      });
      return;
    }
    res.send(file.body);
  } catch (err) {
    if (err instanceof Error && err.message.includes('invalid assetPath')) {
      res.status(400).json({
        errorCode: 'SCHEMA_VALIDATION_FAILED',
        message: err.message,
      });
      return;
    }
    sendError(res, err);
  }
};

const resolvePathWithinRoot = (
  rootPath: string,
  childPath: string,
): string | null => {
  const absolutePath = path.resolve(rootPath, childPath);
  return isPathWithinRoot(rootPath, absolutePath) ? absolutePath : null;
};

function rejectNonLocalRequest(req: Request, res: Response): boolean {
  const remoteAddress = req.socket.remoteAddress;
  if (isLoopbackAddress(remoteAddress)) return false;
  res.status(403).json({
    errorCode: 'RUNTIME_VALIDATION_FAILED',
    message: 'Variant session routes are only accepted from loopback clients.',
  });
  return true;
}

function stateForSession(
  orchestrator: AgentVariantsOrchestrator,
  sessionId: string,
): Record<string, unknown> {
  const stage = orchestrator.getStage(sessionId);
  const briefs = orchestrator.getBriefs(sessionId);
  const progress = orchestrator.getProgress(sessionId);
  const summary =
    stage === 'ready' ||
    stage === 'degraded' ||
    stage === 'failed' ||
    stage === 'cancelled'
      ? orchestrator.getSummary(sessionId)
      : null;
  const variants = orchestrator.getVariants(sessionId);
  const projectContext = orchestrator.getProjectContext(sessionId);
  const activeProjectContext = toActiveProjectContext(projectContext);
  const destinationPath =
    activeProjectContext.kind === 'fresh'
      ? activeProjectContext.workspacePath
      : undefined;
  return {
    sessionId,
    stage,
    briefs,
    progress,
    summary,
    variants,
    projectContext: activeProjectContext,
    ...(destinationPath ? { destinationPath } : {}),
  };
}

const toActiveProjectContext = (
  projectContext: ProjectContext,
): ActiveProjectContext => {
  if (projectContext.kind === 'existing') {
    return { kind: 'existing' };
  }
  return {
    kind: 'fresh',
    workspacePath: projectContext.workspacePath,
    workspaceRoot: projectContext.workspaceRoot,
    framework: projectContext.framework,
    designContext: projectContext.designContext?.map((entry) =>
      entry.kind === 'slug'
        ? { kind: 'slug', slug: entry.slug }
        : { kind: 'markdown', label: entry.label },
    ),
    ...(projectContext.variantContext
      ? {
          sourceContext: {
            sourceCount: projectContext.variantContext.userContext.filter(
              (source) => source.transport !== 'prompt',
            ).length,
            isSourceGrounded: Boolean(
              projectContext.variantContext.rivetMetadata.length ||
              projectContext.designContext?.length,
            ),
          },
        }
      : {}),
  };
};

const manifestKind = (
  manifest: VariantHistoryManifest,
): 'diff' | 'project-created' => {
  return manifest.artifact.kind === 'diff' ? 'diff' : 'project-created';
};

const injectBaseHref = (html: string, baseHref: string): string =>
  insertHtmlHeadElements(html, [
    {
      tagName: 'base',
      markup: `<base href="${baseHref.replace(/"/g, '&quot;')}">`,
    },
  ]);

function sendError(res: import('express').Response, err: unknown): void {
  if (err instanceof AgentVariantsError) {
    log.warn(`agent-variants route error: ${err.code}: ${err.detail}`);
    res.status(statusForCode(err.code)).json({
      errorCode: err.code,
      message: err.detail,
    });
    return;
  }
  log.error('Unexpected error in agent-variants route', err);
  const message = errorMessage(err, 'Unknown error');
  res.status(500).json({ errorCode: 'RUNTIME_VALIDATION_FAILED', message });
}

function statusForCode(code: string): number {
  switch (code) {
    case 'SESSION_NOT_FOUND':
    case 'WORK_ITEM_NOT_FOUND':
      return 404;
    case 'INVALID_STAGE_ACTION':
    case 'INVALID_TRANSITION':
    case 'STALE_LEASE':
    case 'LEASE_EXPIRED':
    case 'LEASE_MISMATCH':
    case 'PENDING_CHANGE_CONFLICT':
    case 'MISSING_REQUIRED_INPUT':
      return 409;
    case 'SCHEMA_VALIDATION_FAILED':
    case 'SOURCE_CONTEXT_INVALID':
    case 'SOURCE_CONTEXT_TOO_LARGE':
      return 400;
    default:
      return 500;
  }
}
